-- NFL rushing by season, all backs and QBs: carries, yards, ybc, yaco, explosive, stuffs, missed forced
with ps as (select s.year, p.player__position pos, s.stats__rush r, s.stats__rush_yds y, s.stats__ybc ybc, s.stats__yaco yaco, s.stats__explosive_runs ex, s.stats__stuffs st, s.stats__forced_missed fm, s.stats__rush_epa epa, s.stats__rush_first f1, s.stats__rush_td td from people__pro__seasons s join people p on p._row = s._parent union all select s.year, a.player__position, s.stats__rush, s.stats__rush_yds, s.stats__ybc, s.stats__yaco, s.stats__explosive_runs, s.stats__stuffs, s.stats__forced_missed, s.stats__rush_epa, s.stats__rush_first, s.stats__rush_td from alumni__pro__seasons s join alumni a on a._row = s._parent) select year, sum(r) carries, round(1.0*sum(y)/sum(r),3) ypc, round(1.0*sum(ybc)/sum(r),3) ybc_pc, round(1.0*sum(yaco)/sum(r),3) yaco_pc, round(1.0*sum(ex)/sum(r),4) expl_rate, round(1.0*sum(st)/sum(r),4) stuff_rate, round(1.0*sum(fm)/sum(r),4) forced_missed_rate, round(sum(epa)/sum(r),4) epa_pc, round(1.0*sum(td)/sum(r),4) td_rate from ps where year between 2025 and 2035 and r > 0 group by year order by year
-- same by carrier position
with ps as (select s.year, p.player__position pos, s.stats__rush r, s.stats__rush_yds y from people__pro__seasons s join people p on p._row = s._parent union all select s.year, a.player__position, s.stats__rush, s.stats__rush_yds from alumni__pro__seasons s join alumni a on a._row = s._parent) select year, pos, sum(r) carries, round(1.0*sum(y)/sum(r),3) ypc from ps where year between 2025 and 2035 and r > 0 and pos in ('RB','QB','WR') group by year, pos order by pos, year
-- blocking and rushing win rates by unit
with ps as (select s.year, case when p.player__position in ('OT','IOL') then 'OL' when p.player__position in ('DT','EDGE') then 'DL' else p.player__position end unit, s.stats__pb_snaps pbs, s.stats__pb_wins pbw, s.stats__rb_snaps rbs, s.stats__rb_wins rbw, s.stats__rush_snaps rs, s.stats__rush_wins rw from people__pro__seasons s join people p on p._row = s._parent union all select s.year, case when a.player__position in ('OT','IOL') then 'OL' when a.player__position in ('DT','EDGE') then 'DL' else a.player__position end, s.stats__pb_snaps, s.stats__pb_wins, s.stats__rb_snaps, s.stats__rb_wins, s.stats__rush_snaps, s.stats__rush_wins from alumni__pro__seasons s join alumni a on a._row = s._parent) select year, unit, round(1.0*sum(pbw)/nullif(sum(pbs),0),4) pass_block_win, round(1.0*sum(rbw)/nullif(sum(rbs),0),4) run_block_win, round(1.0*sum(rw)/nullif(sum(rs),0),4) pass_rush_win from ps where year between 2025 and 2035 and unit in ('OL','DL') group by year, unit order by unit, year
-- starters overall by unit 2016-2035
select year, unit, count(*) n, round(avg(overall),2) mean_overall from (select s.year, case when p.player__position in ('OT','IOL') then 'OL' when p.player__position in ('DT','EDGE') then 'DL' when p.player__position in ('CB','S') then 'DB' else p.player__position end unit, h.overall from people__pro__seasons s join people p on p._row = s._parent join people__player__history h on h._parent = s._parent and h.age = s.year - p.class_of + 18 where s.starts >= 8 and h.level = 'NFL' union all select s.year, case when a.player__position in ('OT','IOL') then 'OL' when a.player__position in ('DT','EDGE') then 'DL' when a.player__position in ('CB','S') then 'DB' else a.player__position end, h.overall from alumni__pro__seasons s join alumni a on a._row = s._parent join alumni__player__history h on h._parent = s._parent and h.age = s.year - a.class_of + 18 where s.starts >= 8 and h.level = 'NFL') where year between 2012 and 2035 and unit in ('OL','DL','RB','QB','WR','LB','DB','TE') group by year, unit order by unit, year
